<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#151a17"><title>Reel Rescue | The restoration bench</title>
<style>
:root{--ink:#18211d;--cream:#f3e8d0;--paper:#ead9b9;--rust:#b65336;--gold:#e1ad57;--line:#647264;--serif:Georgia,'Times New Roman',serif}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#121914;color:var(--cream);font-family:'Trebuchet MS',Verdana,sans-serif;line-height:1.5}a{color:var(--gold)}button,input{font:inherit}button{cursor:pointer}.shell{max-width:1160px;margin:auto;padding:20px clamp(18px,4vw,58px) 72px}.top{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #536055;padding:8px 0 18px;font-size:.72rem;letter-spacing:.18em;text-transform:uppercase}.top a{text-decoration:none}.lamp{display:inline-block;width:9px;height:9px;border-radius:50%;background:#e4ae56;margin-right:10px;box-shadow:0 0 16px #e4ae56}.hero{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(260px,.92fr);align-items:center;gap:clamp(22px,6vw,90px);padding:64px 0 55px}.eyebrow{color:var(--gold);letter-spacing:.24em;text-transform:uppercase;font-size:.72rem;font-weight:700}.hero h1{font-family:var(--serif);font-weight:400;font-size:clamp(3.5rem,8vw,7.2rem);line-height:.91;letter-spacing:-.065em;margin:18px 0 26px}.hero h1 em{color:var(--gold);font-weight:400}.hero p{max-width:520px;color:#b8c2b5;font-size:1.05rem}.hero .hint{font-size:.77rem;color:#87988a;margin-top:30px}.reel-art{position:relative;min-height:270px;display:grid;place-items:center}.reel-art:before{content:'';position:absolute;width:min(90%,360px);aspect-ratio:1;border:2px dashed #526051;border-radius:50%;transform:rotate(-21deg)}.reel{width:min(76%,300px);aspect-ratio:1;border:14px solid #bd8e51;border-radius:50%;background:radial-gradient(circle at center,#272b23 0 11%,#d3a65e 11.5% 17%,#2e322a 18% 26%,transparent 27%),conic-gradient(from 20deg,#d3a65e 0 10deg,#292f28 11deg 85deg,#d3a65e 86deg 97deg,#292f28 98deg 173deg,#d3a65e 174deg 185deg,#292f28 186deg 260deg,#d3a65e 261deg 272deg,#292f28 273deg 349deg,#d3a65e 350deg 360deg);box-shadow:inset 0 0 0 18px #926c3f,0 24px 50px #0008;transform:rotate(10deg)}.reel-art small{position:absolute;right:0;bottom:0;color:#d5af73;font-family:var(--serif);font-style:italic;transform:rotate(-7deg)}.workbench{background:var(--cream);color:var(--ink);border-radius:4px;overflow:hidden;box-shadow:0 35px 80px #0007}.benchbar{background:#26382e;color:var(--cream);display:flex;align-items:center;justify-content:space-between;gap:15px;padding:16px 26px;font-size:.75rem;text-transform:uppercase;letter-spacing:.16em}.benchbar span:last-child{color:#e8b65d}.benchgrid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(260px,.68fr)}.screenwrap{padding:26px;background:#202c24}.screen{position:relative;aspect-ratio:3/2;overflow:hidden;background:#513922;touch-action:none;cursor:ew-resize;box-shadow:0 0 0 12px #121b16,0 0 0 13px #7f8b75}.screen img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;user-select:none;pointer-events:none}.before{filter:sepia(.55) saturate(.5) brightness(.68) contrast(.8) blur(.6px)}.afterClip{position:absolute;inset:0;clip-path:inset(0 0 0 50%)}.after{filter:brightness(1) saturate(1.1) contrast(1.06)}.damage{position:absolute;inset:0;pointer-events:none;background:repeating-linear-gradient(92deg,transparent 0 12%,#fff9 12.1%,transparent 12.4%,transparent 36%,#20140f99 36.1%,transparent 36.4%),radial-gradient(circle at 20% 25%,#fffd 0 1px,transparent 2px),radial-gradient(circle at 82% 65%,#fff8 0 2px,transparent 3px);background-size:100% 100%,34px 39px,61px 67px;opacity:.58;mix-blend-mode:screen}.afterDamage{opacity:.18}.scan{position:absolute;inset:0;background:linear-gradient(transparent 0 49%,#fff2 50%,transparent 51%);opacity:0;pointer-events:none}.playing .scan{opacity:1;animation:scan 2.7s linear infinite}@keyframes scan{to{transform:translateY(100%)}}.divider{position:absolute;z-index:3;left:50%;top:0;bottom:0;width:2px;background:#fff;pointer-events:none;box-shadow:0 0 12px #000}.divider:after{content:'◀  ▶';position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:68px;height:45px;border-radius:30px;background:var(--cream);color:var(--ink);display:grid;place-items:center;font-size:.65rem;letter-spacing:.3em;box-shadow:0 3px 12px #0006}.screenbadge{position:absolute;z-index:4;top:14px;background:#14221bd9;color:#f7ebd2;font-size:.63rem;letter-spacing:.15em;padding:6px 9px;pointer-events:none}.screenbadge.left{left:12px}.screenbadge.right{right:12px}.screen:focus-visible{outline:3px solid var(--gold);outline-offset:15px}.transport{display:flex;align-items:center;justify-content:space-between;gap:12px;color:#dac9a6;font-size:.73rem;letter-spacing:.1em;padding:29px 0 4px}.transport button,.action{border:1px solid #d6ab69;background:#d4a85f;color:#18251c;padding:10px 17px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;font-size:.7rem;border-radius:2px}.transport button:hover,.action:hover{background:#f4d594}.transport button:focus-visible,.action:focus-visible,input:focus-visible{outline:3px solid #eaa33b;outline-offset:3px}.panel{padding:30px 27px;background:#e9dbbf;border-left:1px solid #cbb995}.panel h2{font:400 2rem/1.1 var(--serif);margin:0 0 8px}.panel p{font-size:.82rem;color:#566459;margin:0 0 28px}.control{margin-bottom:27px}.control label{display:flex;justify-content:space-between;font-size:.74rem;text-transform:uppercase;letter-spacing:.11em;font-weight:bold}.control output{color:#a94a2f}.control input{width:100%;accent-color:#ad5135;margin:14px 0 0}.under{display:flex;justify-content:space-between;color:#667366;font-size:.69rem}.note{border-top:1px solid #bdad91;padding-top:18px;font:italic .89rem/1.55 var(--serif);color:#59675c}.lower{display:grid;grid-template-columns:1fr 1fr;gap:clamp(25px,5vw,80px);padding:62px 2px 10px}.lower h2{font:400 clamp(2.2rem,4vw,3.4rem)/1.06 var(--serif);letter-spacing:-.04em;margin:12px 0 19px}.lower p{color:#b0c0b1;font-size:.9rem}.ticket{background:#ebdbb9;color:#243229;padding:28px;transform:rotate(1deg);box-shadow:8px 12px 0 #0005;align-self:start}.ticket:before{content:'TRANSFER DESK  /  ESTIMATE ONLY';display:block;border-bottom:1px dashed #8a8c77;padding-bottom:15px;font-size:.7rem;letter-spacing:.17em;color:#835e38}.ticket label{display:block;font-size:.78rem;font-weight:700;margin-top:19px}.ticket input{display:block;width:100%;border:1px solid #9d9d85;border-radius:0;background:#fbf3e1;padding:10px;margin-top:5px;color:#243229}.results{border-top:1px dashed #8a8c77;margin-top:23px;padding-top:15px;display:grid;grid-template-columns:1fr auto;gap:10px;font-size:.83rem}.results strong{color:#91462e}.ticket small{display:block;margin-top:21px;color:#687266;line-height:1.5}.foot{margin-top:60px;border-top:1px solid #536055;padding-top:23px;color:#8d9d8f;font-size:.8rem}.foot a{color:#e0b16e}@media(max-width:750px){.hero{grid-template-columns:1fr;padding:48px 0 36px}.reel-art{display:none}.benchgrid,.lower{grid-template-columns:1fr}.panel{border-left:0}.screenwrap{padding:18px}.screen{box-shadow:0 0 0 6px #121b16}.screenbadge{font-size:.53rem}.lower{padding-top:45px}.ticket{transform:none}.top{letter-spacing:.09em}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;scroll-behavior:auto!important}}
</style></head><body><div class="shell"><nav class="top"><span><i class="lamp"></i> The home-movie laboratory</span><a href="index.php">← All experiments</a></nav><header class="hero"><div><div class="eyebrow">Field notes / No. 08</div><h1>Reel<br><em>Rescue.</em></h1><p>A tiny restoration bench for the shoebox of Super 8 reels. Pull an old frame into the light, tune the transfer, and find out how much film you might actually have.</p><div class="hint">A fictional frame, not a family photograph. Your adjustments stay in this browser.</div></div><div class="reel-art" aria-hidden="true"><div class="reel"></div><small>hold the light up to it</small></div></header><main><section class="workbench" aria-label="Interactive film restoration bench"><div class="benchbar"><span>✳ &nbsp; Frame 001 / Lakeside afternoon</span><span>8 mm · Preview</span></div><div class="benchgrid"><div class="screenwrap"><div id="screen" class="screen" role="slider" tabindex="0" aria-label="Compare original and restored frame; use left and right arrow keys" aria-valuemin="0" aria-valuemax="100" aria-valuenow="50"><img class="before" src="reel-rescue-scene.webp" alt="A fictional vintage film still of a child at a lakeside beside a turquoise car"><div class="damage"></div><div id="afterClip" class="afterClip"><img id="after" class="after" src="reel-rescue-scene.webp" alt=""><div id="afterDamage" class="damage afterDamage"></div></div><div id="divider" class="divider"></div><div class="screenbadge left">BEFORE</div><div class="screenbadge right">TRANSFER</div><div class="scan"></div></div><div class="transport"><span>⇠ DRAG THE SPLIT TO COMPARE ⇢</span><button id="play" type="button" aria-pressed="false">▶ Run projector</button></div></div><div class="panel"><h2>At the light table</h2><p>Move each dial; the right side changes. Drag the little handle across to inspect your work.</p><div class="control"><label for="exposure">01 / Exposure <output id="exposureOut">50</output></label><input id="exposure" type="range" min="0" max="100" value="50"><div class="under"><span>Underexposed</span><span>Open shadows</span></div></div><div class="control"><label for="colour">02 / Colour <output id="colourOut">50</output></label><input id="colour" type="range" min="0" max="100" value="50"><div class="under"><span>Faded</span><span>Vivid</span></div></div><div class="control"><label for="dust">03 / Dust removal <output id="dustOut">50</output></label><input id="dust" type="range" min="0" max="100" value="50"><div class="under"><span>Authentic grit</span><span>Clean frame</span></div></div><p class="note">The best transfer doesn't erase the years. It just gives the people in them room to breathe.</p></div></div></section><section class="lower"><div><div class="eyebrow">Before you send the reels away</div><h2>What's in the shoebox?</h2><p>Enter your approximate reel count and feet of film per reel. Standard Super 8 at 18 frames per second runs roughly 3 minutes 20 seconds per 50 feet. This is a planning estimate, not a live quote.</p><p>Ask any transfer service about scan resolution, handling, audio, return of originals, and whether they charge setup or delivery fees.</p></div><div class="ticket"><label for="reels">How many reels?</label><input id="reels" type="number" inputmode="numeric" min="1" max="999" value="4"><label for="feet">Feet per reel (approx.)</label><input id="feet" type="number" inputmode="numeric" min="1" max="2000" value="50"><label for="rate">Example transfer rate / foot (CAD)</label><input id="rate" type="number" inputmode="decimal" min="0" max="100" step="0.01" value="0.35"><div class="results" aria-live="polite"><span>Total footage</span><strong id="total">200 ft</strong><span>Approx. screen time</span><strong id="runtime">13m 20s</strong><span>Example transfer cost</span><strong id="cost">$70.00 CAD</strong></div><small>Illustrative rate only; not a current market price. Estimates assume Super 8 at 18 fps and ~50 ft per 3m 20s; actual running time varies by camera speed and reel contents.</small></div></section></main><footer class="foot">Inspired by Jon's <a href="https://jona.ca/2016/01/super8dvd-price-comparison-surrey-bc.html" rel="noopener noreferrer" target="_blank">Super8⇒DVD Price Comparison, Surrey BC area</a>. Original fictional frame generated for this experiment.</footer></div><script>
(()=>{'use strict';const $=id=>document.getElementById(id),screen=$('screen'),clip=$('afterClip'),divider=$('divider'),after=$('after'),damage=$('afterDamage');let split=50;function position(n){split=Math.min(100,Math.max(0,n));clip.style.clipPath='inset(0 0 0 '+split+'%)';divider.style.left=split+'%';screen.setAttribute('aria-valuenow',Math.round(split))}function pointer(e){const r=screen.getBoundingClientRect();position((e.clientX-r.left)/r.width*100)}screen.addEventListener('pointerdown',e=>{screen.setPointerCapture(e.pointerId);pointer(e)});screen.addEventListener('pointermove',e=>{if(e.buttons)pointer(e)});screen.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();position(split+(e.key==='ArrowLeft'?-5:5))}if(e.key==='Home'){position(0)}if(e.key==='End'){position(100)}});function tune(){const exp=+$('exposure').value,col=+$('colour').value,dust=+$('dust').value;for(const [id,value] of [['exposureOut',exp],['colourOut',col],['dustOut',dust]])$(id).textContent=value;after.style.filter='brightness('+(0.72+exp*.007).toFixed(2)+') saturate('+(0.5+col*.015).toFixed(2)+') contrast(1.06)';damage.style.opacity=(.58-dust*.0055).toFixed(2)}for(const id of ['exposure','colour','dust'])$(id).addEventListener('input',tune);tune();let running=false,timer;const play=$('play');play.addEventListener('click',()=>{running=!running;screen.classList.toggle('playing',running);play.textContent=running?'■ Stop projector':'▶ Run projector';play.setAttribute('aria-pressed',String(running));clearInterval(timer);if(running){let frame=0;timer=setInterval(()=>{screen.style.transform='translateY('+(frame++%3===0?1:0)+'px)'},83)}else screen.style.transform=''});function estimate(){let count=Math.min(999,Math.max(0,Number($('reels').value)||0)),feet=Math.min(2000,Math.max(0,Number($('feet').value)||0)),rate=Math.min(100,Math.max(0,Number($('rate').value)||0)),total=count*feet,seconds=Math.round(total*4);$('total').textContent=total.toLocaleString()+' ft';$('runtime').textContent=Math.floor(seconds/3600)?Math.floor(seconds/3600)+'h '+Math.floor(seconds%3600/60)+'m':Math.floor(seconds/60)+'m '+String(seconds%60).padStart(2,'0')+'s';$('cost').textContent='$'+(total*rate).toLocaleString('en-CA',{minimumFractionDigits:2,maximumFractionDigits:2})+' CAD'}for(const id of ['reels','feet','rate'])$(id).addEventListener('input',estimate);estimate()})();
</script></body></html>
